//! Original bounded call-site encoded-value observations, not bootstrap execution.
use super::*;
struct Value{kind:u8,bits:u64}
struct Pools<'a>{strings:usize,kinds:&'a[Kind],fields:usize,methods:usize,protos:usize,handles:usize}
fn value(r:&mut Reader<'_>,at:&mut usize,p:&Pools<'_>,left:&mut usize,depth:usize,cancelled:&dyn Fn()->bool)->Result<Value>{
 if cancelled(){return Err("DEX call-site observation cancelled".into());}if depth>16{return Err("DEX encoded-value depth exceeds16 inspection bound".into());}*left=left.checked_sub(1).ok_or("DEX encoded-value count exceeds65536 inspection bound")?;let first=r.data_range(*at,1,1)?[0];*at+=1;let kind=first&31;let arg=(first>>5)as usize;
 if matches!(kind,0x1c|0x1d){if arg!=0{return Err("DEX nested encoded-value argument is nonzero".into());}let n=if kind==0x1d{let ty=index(r.leb(at)?,p.kinds.len(),"annotation type")?;if p.kinds[ty]!=Kind::Class{return Err("DEX annotation type is not class".into());}r.leb(at)?as usize}else{r.leb(at)?as usize};if n>*left{return Err("DEX nested encoded-value count exceeds remaining bound".into());}let mut prev=None;for _ in 0..n{if kind==0x1d{let name=index(r.leb(at)?,p.strings,"annotation name")?;if prev.map(|v|v>=name).unwrap_or(false){return Err("DEX annotation names duplicate or unordered".into());}prev=Some(name);}value(r,at,p,left,depth+1,cancelled)?;}return Ok(Value{kind,bits:n as u64});}
 if kind==0x1e{if arg!=0{return Err("DEX null value argument is nonzero".into());}return Ok(Value{kind,bits:0});}if kind==0x1f{if arg>1{return Err("DEX Boolean value argument exceeds1".into());}return Ok(Value{kind,bits:arg as u64});}
 let max=match kind{0=>0,2|3=>1,4|0x10|0x15..=0x1b=>3,6|0x11=>7,_=>return Err("DEX encoded-value kind is unsupported/reserved".into())};if arg>max{return Err("DEX encoded-value width argument is invalid".into());}let b=r.data_range(*at,arg+1,1)?;*at+=arg+1;let mut bits=0u64;for(i,&v)in b.iter().enumerate(){bits|=(v as u64)<<(i*8);}
 let count=match kind{0x15=>Some(p.protos),0x16=>Some(p.handles),0x17=>Some(p.strings),0x18=>Some(p.kinds.len()),0x19|0x1b=>Some(p.fields),0x1a=>Some(p.methods),_=>None};if count.map(|n|bits>=n as u64).unwrap_or(false){return Err("DEX encoded-value identifier index exceeds its typed table".into());}Ok(Value{kind,bits})
}
pub(super) fn observe(r:&mut Reader<'_>,maps:&[(u16,usize,usize)],version:u32,strings:&[Vec<u16>],kinds:&[Kind],fields:usize,methods:usize,protos:usize,handles:&[instructions::Handle],rows:&mut Rows,cancelled:&dyn Fn()->bool)->Result<Vec<instructions::Site>>{
 let Some(&(_,count,at))=maps.iter().find(|(k,_,_)|*k==7)else{return Ok(vec![])};if version<38{return Err("DEX call-site table is unavailable in this revision".into());}if count>ITEMS||at<112||at%4!=0{return Err("DEX call-site count/offset exceeds inspection bounds".into());}r.range(at,count.checked_mul(4).ok_or("DEX call-site table extent overflow")?)?;let pools=Pools{strings:strings.len(),kinds,fields,methods,protos,handles:handles.len()};let mut sites=Vec::with_capacity(count);let mut previous=None;let mut left=65536usize;
 for i in 0..count{if cancelled(){return Err("DEX call-site observation cancelled".into());}let offset=r.u32(at+i*4)?as usize;if previous.map(|p|p>offset).unwrap_or(false){return Err("DEX call-site offsets are not ascending".into());}previous=Some(offset);r.data_range(offset,1,1)?;let mut cursor=offset;let n=r.leb(&mut cursor)?as usize;if n<3||n>left{return Err("DEX call-site encoded array length lacks required fields or exceeds value bound".into());}let h=value(r,&mut cursor,&pools,&mut left,0,cancelled)?;let name=value(r,&mut cursor,&pools,&mut left,0,cancelled)?;let proto=value(r,&mut cursor,&pools,&mut left,0,cancelled)?;if h.kind!=0x16||name.kind!=0x17||proto.kind!=0x15{return Err("DEX call-site first values must be method-handle, string and method-type".into());}for _ in 3..n{value(r,&mut cursor,&pools,&mut left,0,cancelled)?;}
  let site=instructions::Site{handle:h.bits as usize,name:name.bits as usize,proto:proto.bits as usize};if i<24{let h=&handles[site.handle];rows.line(format!("Call-site#{i} at byte {offset}: bootstrap handle#{} (kind {}, bound member#{}); name string#{} {}; prototype#{}; {} extra encoded arguments traversed; bootstrap signature/dispatch/return target not verified or executed",site.handle,h.kind,h.index,site.name,display(&strings[site.name]),site.proto,n-3));}sites.push(site);
 }Ok(sites)
}
